// Exact original pure declarations. Generated by capture-agent-runtime.mjs; no file/host adapters.
import { createHash, randomBytes } from "node:crypto";

interface SessionRecord {
  schema?: unknown;
  sessionId?: unknown;
  status?: unknown;
  updatedAt?: unknown;
  createdAt?: unknown;
  trashedAt?: unknown;
  todos?: unknown;
  [key: string]: unknown;
}

export function agentSessionGroup(record: SessionRecord): {
  groupId: string; taskId: string; hostKind: string; hostSessionId: string; groupRecovered: boolean;
} {
  const liveness = record.liveness && typeof record.liveness === "object" ? record.liveness as Record<string, unknown> : {};
  const owner = liveness.owner && typeof liveness.owner === "object" ? liveness.owner as Record<string, unknown> : {};
  const hostSessionId = String(record.hostSessionId || owner.hostSessionId || "").trim();
  const hostKind = String(record.hostKind || "copilot").trim().toLowerCase();
  const taskId = String(record.sessionId || "");
  const retainedGroup = typeof record.groupId === "string" && /^agent_group_[a-f0-9]{64}$/.test(record.groupId) ? record.groupId : "";
  const groupId = hostSessionId
    ? "agent_group_" + createHash("sha256").update(JSON.stringify([hostKind, hostSessionId])).digest("hex")
    : retainedGroup || (taskId ? "agent_group_" + createHash("sha256").update(JSON.stringify(["recovered-session", taskId])).digest("hex") : "");
  return { groupId, taskId, hostKind, hostSessionId, groupRecovered: !hostSessionId };
}

export function projectedAgentSessionStatus(record: SessionRecord): string {
  const status = String(record.status || "unknown");
  if (status !== "running" || !Array.isArray(record.todos) || !record.todos.length) return status;
  const terminal = new Set(["succeeded", "failed", "skipped"]);
  return record.todos.every(todo =>
    todo && typeof todo === "object" && terminal.has(String((todo as { status?: unknown }).status || ""))
  ) ? "completed" : status;
}

export function terminalAgentSessionStatus(record: SessionRecord): boolean {
  return ["completed", "stopped"].includes(projectedAgentSessionStatus(record));
}

export function pkmOwnedAgentSession(record: SessionRecord): boolean {
  return record.origin === "pkm-native" && record.runtimeOwner === "pkm" && record.hostKind === "pkm";
}

export interface AgentSessionLiveness {
  state: "healthy" | "waiting" | "suspected-stalled" | "suspected-interrupted" | "inactive";
  heartbeatAgeSeconds: number | null;
  leaseSeconds: number;
  ownerTransportId: string;
  hostSessionId: string;
}

export function agentSessionLiveness(
  record: SessionRecord,
  waiting = false,
  now = Date.now(),
): AgentSessionLiveness {
  const liveness = record.liveness && typeof record.liveness === "object"
    ? record.liveness as Record<string, unknown>
    : {};
  const owner = liveness.owner && typeof liveness.owner === "object"
    ? liveness.owner as Record<string, unknown>
    : {};
  const configuredLease = typeof liveness.leaseSeconds === "number" && Number.isFinite(liveness.leaseSeconds)
    ? liveness.leaseSeconds
    : 300;
  const leaseSeconds = Math.max(30, configuredLease);
  const heartbeat = Date.parse(String(liveness.heartbeatAt
    || (record.lastActivity && typeof record.lastActivity === "object"
      ? (record.lastActivity as Record<string, unknown>).at
      : "")
    || record.updatedAt
    || ""));
  const heartbeatAgeSeconds = Number.isFinite(heartbeat) ? Math.max(0, (now - heartbeat) / 1000) : null;
  let state: AgentSessionLiveness["state"] = "inactive";
  if (projectedAgentSessionStatus(record) === "running") {
    if (waiting) state = "waiting";
    else if (heartbeatAgeSeconds === null || heartbeatAgeSeconds >= leaseSeconds * 3) state = "suspected-interrupted";
    else if (heartbeatAgeSeconds >= leaseSeconds) state = "suspected-stalled";
    else state = "healthy";
  }
  return {
    state,
    heartbeatAgeSeconds,
    leaseSeconds,
    ownerTransportId: String(owner.transportId || ""),
    hostSessionId: String(owner.hostSessionId || record.hostSessionId || ""),
  };
}

export interface WorkerScope { writeScope?: string[]; resources?: string[]; }

export interface WorkerSlot extends WorkerScope { receiptId: string; chatId: string; parentChatId: string; title: string; temporary?: boolean; released?: boolean; }

export interface WorkerLimits { automatic: number; maximum: number; }

export function workerIsDescendant(slots: readonly WorkerSlot[], ancestorChatId: string, workerChatId: string, includeReleased = false): boolean {
  const parents = new Map(slots.filter(slot => includeReleased || !slot.released).map(slot => [slot.chatId, slot.parentChatId]));
  const visited = new Set<string>();
  let current = parents.get(workerChatId);
  while (current) {
    if (current === ancestorChatId) return true;
    if (visited.has(current)) throw new Error("Worker tree ancestry contains a cycle.");
    visited.add(current);
    current = parents.get(current);
  }
  return false;
}

export function workerLimits(automatic: number, maximum: number): WorkerLimits {
  if (!Number.isSafeInteger(automatic) || !Number.isSafeInteger(maximum) || automatic < 0 || maximum < 1 || maximum > 1000 || automatic > maximum) {
    throw new Error("Worker limits require 0 <= automatic <= maximum <= 1000.");
  }
  return { automatic, maximum };
}

export interface PortalEndpointIdentity {
  endpointId: string;
  name: string;
  chatId?: string;
  chatName?: string;
  deleted: boolean;
  revision: number;
  acceptsIncoming: boolean;
}

export function parsePortalEndpointIdentity(value: unknown): PortalEndpointIdentity {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Invalid Portal endpoint state.");
  const item = value as Record<string, unknown>;
  for (const [field, limit] of [["endpointId", 200], ["name", 200], ["chatId", 200], ["chatName", 200]] as const) {
    if (item[field] === undefined && (field === "chatId" || field === "chatName")) continue;
    if (typeof item[field] !== "string" || !item[field] || (item[field] as string).length > limit || /[\x00-\x1f]/.test(item[field] as string)) throw new Error("Invalid Portal endpoint identity.");
  }
  if (typeof item.deleted !== "boolean" || typeof item.acceptsIncoming !== "boolean" || !Number.isSafeInteger(item.revision) || (item.revision as number) < 0) throw new Error("Invalid Portal endpoint revision or enabled state.");
  if (Object.keys(item).some(key => !["endpointId", "name", "chatId", "chatName", "deleted", "revision", "acceptsIncoming"].includes(key))) throw new Error("Unsupported Portal endpoint field.");
  return { endpointId: item.endpointId as string, name: item.name as string, deleted: item.deleted, revision: item.revision as number,
    acceptsIncoming: item.acceptsIncoming, ...(item.chatId === undefined ? {} : { chatId: item.chatId as string }), ...(item.chatName === undefined ? {} : { chatName: item.chatName as string }) };
}

export interface AgentSnapshotSummary {
  snapshotId: string;
  name?: string;
  magicCode: string;
  sourceSessionId: string;
  sourceHostSessionId: string;
  /** "pkm" for PKM Chat Snapshots (conversation + Recipes); other values are retired external agents. */
  sourceHostKind: string;
  task: string;
  projectId: string;
  agent: { name: string; product: string };
  reason: string;
  createdAt: string;
  recipeRunCount: number;
  todoCount: number;
  checkpoint?: {
    checkpointId: string;
    sequence: number;
    createdAt: string;
    reason: string;
  };
  recoveryCount: number;
}

export interface AgentSnapshotContents {
  snapshotId: string;
  session: Record<string, unknown>;
  recipeRuns: unknown[];
}

export interface AgentSnapshotRecovery {
  /** Fields merged into the new PKM Chat Session record. */
  session: Record<string, unknown>;
  /** Cloned Recipe runs with fresh ids; empty for Snapshots without Recipes. */
  recipeRuns: Array<Record<string, any>>;
  continuationTodoCreated: boolean;
}

function continuationTodo(session: any, sessionId: string, now: string): Record<string, unknown> | undefined {
  const todos = Array.isArray(session.todos) ? session.todos : [];
  if (todos.some((todo: any) => todo && ["pending", "running", "paused"].includes(String(todo.status || "")))) return undefined;
  const checkpoints = Array.isArray(session.checkpoints) ? session.checkpoints : [];
  const latest = checkpoints.at(-1) && typeof checkpoints.at(-1) === "object" ? checkpoints.at(-1) : {};
  const state = latest.state && typeof latest.state === "object" ? latest.state : {};
  const summary = String(state.summary || session.summary || "Continue from the recovered Agent Snapshot.").trim();
  const next = Array.isArray(state.next_actions) ? state.next_actions : Array.isArray(state.nextActions) ? state.nextActions : [];
  const actions = next.map((value: unknown) => String(value).trim()).filter(Boolean).slice(0, 12);
  const details = actions.length ? `${summary}\n\nNext actions:\n${actions.map((action: string) => `- ${action}`).join("\n")}` : summary;
  return {
    todoId: `todo_${createHash("sha256").update(`${sessionId}:resume-snapshot`, "utf8").digest("hex").slice(0, 20)}`,
    title: "Continuing recovered Agent Snapshot", details: details.slice(0, 12000),
    actionType: "resume_snapshot", status: "pending", createdAt: now, updatedAt: now,
  };
}

export function agentSnapshotRecovery(contents: AgentSnapshotContents, snapshot: Pick<AgentSnapshotSummary, "snapshotId" | "magicCode" | "sourceSessionId">,
  sessionId: string, now = new Date().toISOString(), recoveryKey = randomBytes(16).toString("hex")): AgentSnapshotRecovery {
  const source = contents.session as any;
  const runIdMap = new Map<string, string>();
  for (const run of contents.recipeRuns as any[]) {
    const runId = String(run?.runId || "");
    if (runId) runIdMap.set(runId, `recipe_run_${createHash("sha256").update(`${runId}:${recoveryKey}`, "utf8").digest("hex").slice(0, 24)}`);
  }
  const mapRun = (id: unknown) => runIdMap.get(String(id || "")) || "";
  const recipeRuns = (contents.recipeRuns as any[]).filter(run => runIdMap.has(String(run?.runId || ""))).map(original => {
    const run = JSON.parse(JSON.stringify(original));
    run.runId = mapRun(original.runId);
    run.agentSessionId = sessionId;
    run.receipts = {};
    if (run.parent && typeof run.parent === "object") run.parent.runId = mapRun(run.parent.runId);
    for (const [nodeId, record] of Object.entries<any>(run.nodes || {})) {
      if (record?.state === "running") {
        run.nodes[nodeId] = { state: "pending", ...(record.childRunId ? { childRunId: mapRun(record.childRunId) } : {}), ...(record.childRecipeId ? { childRecipeId: record.childRecipeId } : {}) };
      } else if (record?.childRunId) record.childRunId = mapRun(record.childRunId);
    }
    return run;
  });
  const todos = (Array.isArray(source.todos) ? source.todos : []).filter((todo: any) => todo && typeof todo === "object").map((original: any) => {
    const todo = JSON.parse(JSON.stringify(original));
    if (["running", "paused"].includes(todo.status)) {
      todo.status = "pending";
      for (const field of ["startedAt", "pausedAt", "pauseReason", "resumedAt"]) delete todo[field];
      todo.updatedAt = now;
    }
    if (todo.recipeRunId) todo.recipeRunId = mapRun(todo.recipeRunId);
    if (Array.isArray(todo.recipeRunIds)) todo.recipeRunIds = todo.recipeRunIds.map(String).filter((id: string) => runIdMap.has(id)).map(mapRun);
    return todo;
  });
  const continuation = continuationTodo({ ...source, todos }, sessionId, now);
  if (continuation) todos.push(continuation);
  return {
    session: {
      todos, checkpoints: Array.isArray(source.checkpoints) ? JSON.parse(JSON.stringify(source.checkpoints)) : [],
      recipeRunIds: (Array.isArray(source.recipeRunIds) ? source.recipeRunIds : []).map(String).filter((id: string) => runIdMap.has(id)).map(mapRun),
      ...(Array.isArray(source.recipeTreeEdges) ? { recipeTreeEdges: source.recipeTreeEdges.filter((edge: any) => runIdMap.has(String(edge?.fromRunId || "")) && runIdMap.has(String(edge?.toRunId || "")))
        .map((edge: any) => ({ ...edge, fromRunId: mapRun(edge.fromRunId), toRunId: mapRun(edge.toRunId) })) } : {}),
      ...(source.projectId ? { projectId: String(source.projectId) } : {}),
      provenance: { kind: "agent-snapshot", snapshotId: snapshot.snapshotId, magicCode: snapshot.magicCode, sourceSessionId: snapshot.sourceSessionId },
      recoveredAt: now,
    },
    recipeRuns, continuationTodoCreated: !!continuation,
  };
}

